import os,json,subprocess
from pathlib import Path
old_paths={"/etc/pink-vpn":"/srv/projects/pink-iptv/vpn/gateway","/var/lib/pink-vpn":"/srv/projects/pink-iptv/vpn/data"}
out={"aliases":{},"files_with_old_refs":{},"live_refs":{},"scanned_files":0,"units":{}}
for old,new in old_paths.items():
 p=Path(old);out["aliases"][old]={"is_symlink":p.is_symlink(),"matches_target":p.is_symlink() and p.resolve(strict=False)==Path(new)}
 out["files_with_old_refs"][old]=[]
scan_roots=("/etc/systemd/system","/etc/nginx","/etc/cron.d","/etc/wireguard","/usr/local/bin","/usr/local/sbin","/srv/projects/pink-iptv/infra","/srv/projects/pink-iptv/backend","/srv/projects/pink-iptv/vpn")
for base in scan_roots:
 p=Path(base)
 if not p.is_dir():continue
 for cur,dirs,files in os.walk(p,followlinks=False):
  if len(Path(cur).relative_to(p).parts)>5:dirs[:]=[];continue
  dirs[:]=[x for x in dirs if x not in ("node_modules",".venv","__pycache__",".git","archive","data","build","dist","tests","alembic","private")]
  for n in files:
   f=Path(cur)/n
   try:
    if f.is_symlink() or not f.is_file() or f.stat().st_size>120000:continue
    out["scanned_files"]+=1
    b=f.read_bytes()
    for old in old_paths:
     if old.encode() in b:out["files_with_old_refs"][old].append(str(f))
   except OSError:pass
pidproc=subprocess.run(["systemctl","show","pink-vpn","-p","MainPID","--value"],capture_output=True,text=True,timeout=6)
pid=int(pidproc.stdout.strip() or 0)
out["units"]["vpn_main_pid"]=pid
if pid>0:
 try:
  q=Path("/proc")/str(pid)
  out["units"]["canonical_command"]=b"/srv/projects/pink-iptv/vpn/gateway" in (q/"cmdline").read_bytes()
  out["units"]["legacy_command"]=any(x.encode() in (q/"cmdline").read_bytes() for x in old_paths)
  out["units"]["legacy_environment"]=any(x.encode() in (q/"environ").read_bytes() for x in old_paths)
 except OSError:pass
for old in old_paths:
 out["live_refs"][old]=[]
 for proc in Path("/proc").iterdir():
  if not proc.name.isdecimal() or int(proc.name) in (os.getpid(),os.getppid()):continue
  try:
   cmd=(proc/"comm").read_text().strip()
   if cmd not in ("python3","python","gunicorn","uvicorn","nginx","wg","wg-quick"):continue
   if old.encode() in (proc/"cmdline").read_bytes() or old.encode() in (proc/"environ").read_bytes():out["live_refs"][old].append({"pid":int(proc.name),"comm":cmd})
  except OSError:pass
print(json.dumps(out,sort_keys=True))
